// Ein Beispiel-Gespräch, damit du die Vorlage sofort testen kannst.
// Später kommt das echte Gespräch über "Gespräch kommt rein" (links oben).
return [{
  json: {
    kunde: 'Physiopraxis am Park',
    transkript: `Agentur: Schön, dass es losgeht. Lass uns kurz durchgehen, was ihr euch wünscht.
Kunde: Wichtigstes Thema ist Instagram. Wir posten gerade gar nicht, wollen aber ab nächsten Monat drei Mal die Woche etwas zeigen. Vor allem Übungen und das Team.
Agentur: Gibt es schon Fotos vom Team?
Kunde: Nein, die bräuchten wir. Ein Fotograf wäre super, gern noch diesen Monat.
Agentur: Okay. Und die Website?
Kunde: Die ist alt. Die Online-Terminbuchung soll prominenter werden, und die Leistungsseiten sind veraltet. Die Texte schicke ich euch bis Freitag.
Kunde: Außerdem wollen wir Google Ads für "Physiotherapie Fulda" testen, Budget so 500 Euro im Monat.
Agentur: Dann brauchen wir Zugang zu eurem Google-Konto und zur Website.
Kunde: Die Zugänge schicke ich heute noch. Unser Logo gibt es nur als JPG, ist das schlimm?
Agentur: Wir bauen es als Vektor nach. Nächster Termin: Kick-off mit dem ganzen Team in zwei Wochen?
Kunde: Passt, am liebsten dienstags.`,
  },
}];

// ============ HIER DEIN TEAM EINTRAGEN ============
// rolle:      so heißt die Rolle in deiner Agentur
// name/email: wer die Aufgaben bekommt
// zustaendig: wofür die Person zuständig ist (daran erkennt die KI, wer was bekommt)
const TEAM = [
  { rolle: 'Projektleitung', name: 'Lisa',  email: 'lisa@deine-agentur.de',  zustaendig: 'Kick-off, Termine, Zugänge, Abstimmung mit dem Kunden, Angebote' },
  { rolle: 'Design',         name: 'Tom',   email: 'tom@deine-agentur.de',   zustaendig: 'Logo, Moodboards, Layouts, Grafiken, Fotos, Webdesign' },
  { rolle: 'Content',        name: 'Mia',   email: 'mia@deine-agentur.de',   zustaendig: 'Texte, Redaktionsplan, Social Media, Blog, Website-Texte' },
  { rolle: 'Ads',            name: 'Jonas', email: 'jonas@deine-agentur.de', zustaendig: 'Google Ads, Meta Ads, Tracking, Budgets, Reporting' },
];
const AGENTUR = 'Deine Agentur';        // erscheint in den Mails
const STANDARD_ROLLE = 'Projektleitung'; // bekommt alles, was die KI nicht zuordnen kann
// ==================================================

const d = $input.first().json;
const quelle = d.body || d; // vom Webhook kommt alles in "body"
return [{
  json: {
    kunde: String(quelle.kunde || 'Neuer Kunde'),
    transkript: String(quelle.transkript || ''),
    team: TEAM,
    agentur: AGENTUR,
    standardRolle: STANDARD_ROLLE,
  },
}];

// Baut die Anfrage an die KI. Hier musst du normalerweise nichts ändern.
const d = $input.first().json;
const rollen = d.team.map(t => `- ${t.rolle}: ${t.zustaendig}`).join('\n');

const system = `Du bist Projektassistenz in einer Marketing-Agentur.
Du bekommst das Transkript eines Onboarding-Gesprächs mit einem neuen Kunden.
Finde jede konkrete Aufgabe, die die Agentur nach dem Gespräch erledigen muss, und ordne sie genau einer Rolle zu.

Rollen im Team:
${rollen}

Regeln:
- Nur echte To-dos der Agentur, keine Aufgaben des Kunden. Wenn der Kunde etwas liefern muss, wird daraus eine Aufgabe "nachhalten" für die Projektleitung.
- Titel kurz und als Tätigkeit formuliert (z. B. "Moodboard für Instagram erstellen").
- rolle muss exakt einer der Rollen oben entsprechen. Wenn unklar: "${d.standardRolle}".
- faellig_in_tagen: realistische Anzahl Arbeitstage ab heute, Zeitangaben aus dem Gespräch beachten.
- prioritaet: "hoch", "mittel" oder "niedrig".
- aus_dem_gespraech: die Stelle aus dem Gespräch in wenigen Worten, damit klar ist, woher die Aufgabe kommt.

Antworte nur mit JSON in diesem Format:
{"aufgaben":[{"titel":"","beschreibung":"","rolle":"","prioritaet":"","faellig_in_tagen":0,"aus_dem_gespraech":""}]}`;

return [{
  json: {
    ...d,
    request: {
      model: 'gpt-4o-mini',
      temperature: 0.2,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: `Kunde: ${d.kunde}\n\nTranskript:\n${d.transkript}` },
      ],
    },
  },
}];

// Nimmt die Aufgaben der KI, ordnet sie den Personen zu
// und baut pro Person eine Mail mit ihren Aufgaben.
const ctx = $('Anfrage an die KI bauen').first().json;
const antwort = $input.first().json;
let aufgaben = [];
try {
  aufgaben = JSON.parse(antwort.choices[0].message.content).aufgaben || [];
} catch (e) {
  throw new Error('Die KI hat kein gültiges JSON geliefert: ' + e.message);
}

const team = ctx.team;
const standard = team.find(t => t.rolle === ctx.standardRolle) || team[0];
const finde = rolle => team.find(t => t.rolle.toLowerCase() === String(rolle || '').toLowerCase()) || standard;

// Fälligkeit: Arbeitstage ab heute (Wochenenden werden übersprungen)
const faellig = tage => {
  const d = new Date();
  let n = Math.max(1, Number(tage) || 3);
  while (n > 0) { d.setDate(d.getDate() + 1); if (d.getDay() !== 0 && d.getDay() !== 6) n--; }
  return d.toLocaleDateString('de-DE', { weekday: 'short', day: '2-digit', month: '2-digit' });
};

const farbe = { hoch: '#b4441f', mittel: '#8a6210', niedrig: '#6e675c' };
const proPerson = {};
for (const a of aufgaben) {
  const p = finde(a.rolle);
  (proPerson[p.email] ||= { ...p, aufgaben: [] }).aufgaben.push({ ...a, faellig: faellig(a.faellig_in_tagen) });
}

return Object.values(proPerson).map(p => {
  const liste = p.aufgaben.map(a => `
    <tr><td style="padding:14px 0;border-bottom:1px solid #eee;">
      <div style="font-weight:700;font-size:15px;color:#1c1712;">${a.titel}</div>
      <div style="margin-top:4px;font-size:14px;color:#3a332b;">${a.beschreibung || ''}</div>
      <div style="margin-top:6px;font-size:12px;color:#6e675c;">
        <span style="color:${farbe[a.prioritaet] || '#6e675c'};font-weight:700;">${(a.prioritaet || 'mittel').toUpperCase()}</span>
        · fällig ${a.faellig} · aus dem Gespräch: „${a.aus_dem_gespraech || '-'}“
      </div>
    </td></tr>`).join('');
  const html = `<div style="font-family:Arial,sans-serif;max-width:600px;">
    <p style="font-size:15px;color:#1c1712;">Hi ${p.name},</p>
    <p style="font-size:15px;color:#3a332b;">aus dem Onboarding-Gespräch mit <b>${ctx.kunde}</b> sind ${p.aufgaben.length} Aufgabe(n) für dich (${p.rolle}) rausgekommen:</p>
    <table style="width:100%;border-collapse:collapse;">${liste}</table>
    <p style="font-size:12px;color:#6e675c;margin-top:20px;">Automatisch verteilt von ${ctx.agentur}. Wenn etwas nicht zu dir gehört, gib es kurz an die Projektleitung weiter.</p>
  </div>`;
  return { json: { name: p.name, email: p.email, rolle: p.rolle, kunde: ctx.kunde, anzahl: p.aufgaben.length, aufgaben: p.aufgaben, html } };
});
